import fsExtra from"fs-extra";export async function outputFile(r,e){return fsExtra.outputFile(r,e,"utf8")}export async function copy(r,e){return fsExtra.copy(r,e)}export async function copySync(r,e){return fsExtra.copySync(r,e)}export async function readFile(r){return fsExtra.readFile(r,"utf8")}export function readFileSync(r){return fsExtra.readFileSync(r,"utf8")}export async function deleteFile(r){return fsExtra.remove(r)}export async function remove(r){return fsExtra.remove(r)}export function removeSync(r){return fsExtra.removeSync(r)}export async function ensureDir(r){return fsExtra.ensureDir(r)}export function ensureDirSync(r){fsExtra.ensureDirSync(r)}export async function isFile(r){const e=await fsExtra.stat(r).catch(()=>!1);return!(!e||!e.isFile())}export function isValidMimeType(r,e){const t=e.replace(/\*/g,".*");return new RegExp(`^${t}$`).test(r)}